// metal-archive: compile a Metal source (one of llama.cpp's autogenerated/ggml-metal-embed-KIND.metal) with Apple's compiler for this GPU
// and keep the GPU machine code: every kernel that builds without function constants goes into a
// MTLBinaryArchive, serialized to a file. Its code is what Apple's compiler makes of the kernels whose Vulkan
// twins Mesa's compiler builds on Linux; disassemble it there (e.g. dougallj/applegpu) to compare.
// The archive is Apple's compiler output for this machine: for study here, not for publishing.
// Build (macOS): clang -O2 -fobjc-arc -framework Metal -framework Foundation metal-archive.m -o metal-archive
// Run:          ./metal-archive ggml-metal-embed.metal out.metallib > list.txt
#import <Foundation/Foundation.h>
#import <Metal/Metal.h>

int main(int argc, const char **argv) {
    @autoreleasepool {
        if (argc != 3) { fprintf(stderr, "usage: %s SOURCE.metal OUT.metallib\n", argv[0]); return 2; }
        id<MTLDevice> dev = MTLCreateSystemDefaultDevice();
        NSError *err = nil;
        NSString *src = [NSString stringWithContentsOfFile:@(argv[1]) encoding:NSUTF8StringEncoding error:&err];
        if (!src) { fprintf(stderr, "read: %s\n", err.description.UTF8String); return 1; }
        MTLCompileOptions *opt = [MTLCompileOptions new];
        opt.mathMode = MTLMathModeFast;
        // The macros llama.cpp sets when it compiles these sources (ggml-metal-device.m): without
        // GGML_METAL_EMBED_LIBRARY the quantized kernels look for ggml-common.h on disk and fail to compile.
        NSMutableDictionary *prep = [NSMutableDictionary dictionary];
        prep[@"GGML_METAL_EMBED_LIBRARY"] = @"1";
        if ([dev supportsFamily:MTLGPUFamilyMetal3]) prep[@"GGML_METAL_HAS_BF16"] = @"1";
        opt.preprocessorMacros = prep;
        id<MTLLibrary> lib = [dev newLibraryWithSource:src options:opt error:&err];
        if (!lib) { fprintf(stderr, "compile: %s\n", err.description.UTF8String); return 1; }
        MTLBinaryArchiveDescriptor *ad = [MTLBinaryArchiveDescriptor new];
        id<MTLBinaryArchive> ar = [dev newBinaryArchiveWithDescriptor:ad error:&err];
        if (!ar) { fprintf(stderr, "archive: %s\n", err.description.UTF8String); return 1; }
        unsigned ok = 0, skipped = 0;
        for (NSString *name in [lib.functionNames sortedArrayUsingSelector:@selector(compare:)]) {
            id<MTLFunction> f = [lib newFunctionWithName:name];
            if (!f || f.functionType != MTLFunctionTypeKernel) { skipped++; continue; }
            if (f.functionConstantsDictionary.count) { printf("needs function constants: %s\n", name.UTF8String); skipped++; continue; }
            MTLComputePipelineDescriptor *pd = [MTLComputePipelineDescriptor new];
            pd.computeFunction = f;
            NSError *e = nil;
            id<MTLComputePipelineState> ps = [dev newComputePipelineStateWithDescriptor:pd options:0 reflection:nil error:&e];
            if (!ps || ![ar addComputePipelineFunctionsWithDescriptor:pd error:&e]) {
                printf("failed: %s: %s\n", name.UTF8String, e.localizedDescription.UTF8String); skipped++; continue;
            }
            printf("kernel %s threadExecutionWidth %lu maxTotalThreadsPerThreadgroup %lu staticThreadgroupMemoryLength %lu\n",
                   name.UTF8String, ps.threadExecutionWidth, ps.maxTotalThreadsPerThreadgroup, ps.staticThreadgroupMemoryLength);
            ok++;
        }
        if (![ar serializeToURL:[NSURL fileURLWithPath:@(argv[2])] error:&err]) {
            fprintf(stderr, "serialize: %s\n", err.description.UTF8String); return 1;
        }
        printf("archived %u kernels, skipped %u, into %s\n", ok, skipped, argv[2]);
    }
    return 0;
}
